using System;
using System.Collections.Generic;
using System.Globalization;
using System.Text;

namespace DriveTheCityII.Core.Career
{
    /// <summary>
    /// Bus shifts on real city bus lines (SPEC-BUS; REQ-BUS-001, REQ-BUS-002). Stops are served in line order with
    /// mod-owned CAREER passengers generated by the mission's seeded generator. Native passengers are never read,
    /// carried or counted, and native ridership is never changed (REQ-CITY-001). A modified line is replanned; a
    /// deleted line ends the shift with a no-fault cancellation that pays served stops in full.
    /// </summary>
    internal sealed class BusRules : CareerRules
    {
        internal const string FailSevereKey = "DTC.Bus.Fail.SevereContacts";

        public override CareerKind Kind => CareerKind.Bus;

        public override Unlock RequiredUnlock => Unlock.BusShifts;

        /// <summary>Version signature of a line's stop sequence (stop ids and access points rounded to 0.5 m).</summary>
        public static string Signature(TransitLineInfo line)
        {
            var sb = new StringBuilder();
            sb.Append(line.Id).Append('|');
            if (line.Stops != null)
            {
                foreach (PlaceInfo p in line.Stops)
                {
                    if (p == null)
                    {
                        continue;
                    }
                    sb.Append(p.Id).Append('@')
                        .Append(Math.Round(p.Access.X * 2).ToString(CultureInfo.InvariantCulture)).Append(',')
                        .Append(Math.Round(p.Access.Z * 2).ToString(CultureInfo.InvariantCulture)).Append(';');
                }
            }
            return StableHash.Hex(StableHash.Fnv1a64(sb.ToString()));
        }

        private static List<PlaceInfo> ValidStops(TransitLineInfo line)
        {
            var list = new List<PlaceInfo>();
            if (line?.Stops == null)
            {
                return list;
            }
            foreach (PlaceInfo p in line.Stops)
            {
                if (p != null && !string.IsNullOrEmpty(p.Id) && p.Access.IsFinite)
                {
                    list.Add(p);
                }
            }
            return list;
        }

        public override List<MissionOffer> Generate(CareerService svc, MapPoint near, double now, int count)
        {
            var offers = new List<MissionOffer>();
            foreach (TransitLineInfo line in svc.BusLinesSorted())
            {
                if (offers.Count >= count)
                {
                    break;
                }
                List<PlaceInfo> stops = ValidStops(line);
                if (stops.Count < CareerBalance.BusMinStops)
                {
                    continue;
                }
                var est = new List<RouteEstimate>();
                bool ok = true;
                for (int i = 0; i < stops.Count && ok; i++)
                {
                    RouteEstimate e = i == 0 ? svc.EstimateRoute(near, stops[0].Id, VehicleClass.Bus) : svc.EstimateRoute(stops[i - 1].Access, stops[i].Id, VehicleClass.Bus);
                    ok = e.IsReachable;
                    est.Add(e);
                }
                if (!ok)
                {
                    continue;
                }
                offers.Add(Build(svc, near, now, line, stops, est));
            }
            return offers;
        }

        private MissionOffer Build(CareerService svc, MapPoint near, double now, TransitLineInfo line, List<PlaceInfo> stops, List<RouteEstimate> est)
        {
            MissionOffer o = svc.NewOffer(CareerKind.Bus, near, now);
            double planned = 0;
            double plannedSeconds = 0;
            for (int i = 0; i < stops.Count; i++)
            {
                o.LegTemplates.Add(Leg(i, i, LegKind.Stop, stops[i], CareerBalance.BusStopRadius, est[i].DistanceMeters, est[i].TimeSeconds, 0));
                if (i > 0)
                {
                    planned += est[i].DistanceMeters;
                    plannedSeconds += est[i].TimeSeconds + CareerBalance.BusDwellAllowanceSeconds;
                }
            }
            long stopPay = CareerBalance.BusPerStopCents * stops.Count;
            long expectedPassengers = CareerBalance.BusPerPassengerCents * (stops.Count - 1) * (CareerBalance.BusMaxWaitingPerStop / 2);
            o.TitleKey = "DTC.Bus.Offer.Title";
            o.Title = "Bus shift on line " + (string.IsNullOrEmpty(line.Name) ? CareerMath.Inv(line.Number) : line.Name) + " (" + stops.Count + " stops)";
            o.ApproachMeters = est[0].DistanceMeters;
            o.ApproachSeconds = est[0].TimeSeconds;
            o.PlannedMeters = planned;
            o.PlannedSeconds = plannedSeconds;
            o.ContractValueCents = stopPay + expectedPassengers;
            o.PayMinCents = CareerMath.RoundCents(stopPay * CareerBalance.EvalLowMultiplier);
            o.PayMaxCents = CareerMath.RoundCents((stopPay + expectedPassengers) * (1 + CareerBalance.BusPunctualityBonusMax) * CareerBalance.EvalHighMultiplier);
            o.XpPreview = Progression.MissionXp(planned, 100);
            o.LineId = line.Id;
            o.LineName = line.Name;
            o.StopCount = stops.Count;
            o.AllowedClasses.Add(VehicleClass.Bus);
            o.ProvidesServiceVehicle = true;
            o.ServiceModelId = CareerCatalog.ServiceBusModelId;
            List<PlaceInfo> depots = svc.QueryPlacesByDistance(new[] { PlaceKind.Depot }, stops[0].Access, 5000, 1);
            o.ServiceSpawnPlaceId = depots.Count > 0 ? depots[0].Id : stops[0].Id;
            o.BusTemplate = new BusTerms { LineId = line.Id, LineName = line.Name, LineNumber = line.Number, Signature = Signature(line) };
            return o;
        }

        public override void OnActivated(CareerService svc, Mission m, double now)
        {
            MissionLeg current = m.CurrentLeg;
            if (current != null && m.Bus.WaitingStopId != current.Place.Id)
            {
                GenerateWaiting(m, current);
            }
        }

        public override bool CheckCapacity(Mission m, CareerVehicle v, out string reasonText)
        {
            reasonText = null;
            return true;
        }

        /// <summary>Career passengers waiting at a stop: 0..15, destinations spread over downstream stops (SPEC-BUS 5).</summary>
        private static void GenerateWaiting(Mission m, MissionLeg stop)
        {
            BusTerms t = m.Bus;
            t.Waiting.Clear();
            t.WaitingStopId = stop.Place.Id;
            var downstream = new List<MissionLeg>();
            foreach (MissionLeg l in m.Legs)
            {
                if (l.Index > stop.Index && !l.IsResolved)
                {
                    downstream.Add(l);
                }
            }
            if (downstream.Count == 0)
            {
                return;
            }
            int n = m.Rng.NextRange(0, CareerBalance.BusMaxWaitingPerStop);
            for (int k = 0; k < n; k++)
            {
                MissionLeg dest = downstream[m.Rng.NextInt(downstream.Count)];
                BusTerms.AddTo(t.Waiting, dest.Place.Id, 1);
            }
        }

        private static int WaitingTotal(BusTerms t)
        {
            int n = 0;
            foreach (PassengerGroup g in t.Waiting)
            {
                n += g.Count;
            }
            return n;
        }

        private static int CountFor(List<PassengerGroup> groups, string stopId)
        {
            foreach (PassengerGroup g in groups)
            {
                if (g.StopId == stopId)
                {
                    return g.Count;
                }
            }
            return 0;
        }

        public override double ServiceSeconds(CareerService svc, Mission m, MissionLeg leg)
        {
            BusTerms t = m.Bus;
            int alight = CountFor(t.Onboard, leg.Place.Id);
            int board = t.WaitingStopId == leg.Place.Id ? Math.Min(WaitingTotal(t), t.Capacity - (t.OnboardCount - alight)) : 0;
            return CareerMath.Clamp(CareerBalance.BusSecondsPerPassenger * (alight + board), CareerBalance.BusMinDwellSeconds, CareerBalance.BusDwellCapSeconds);
        }

        private static List<MissionLeg> Pending(Mission m)
        {
            var list = new List<MissionLeg>();
            foreach (MissionLeg l in m.Legs)
            {
                if (!l.IsResolved)
                {
                    list.Add(l);
                }
            }
            return list;
        }

        public override void BeforeLegs(CareerService svc, Mission m, PlayerSnapshot s, double now)
        {
            List<MissionLeg> pending = Pending(m);
            if (pending.Count == 0)
            {
                return;
            }
            bool slow = s.SpeedMps <= CareerBalance.ServiceSpeedMps;
            // Stopping at a later stop means the earlier ones were skipped.
            for (int i = 1; i < pending.Count && i <= 3; i++)
            {
                MissionLeg later = pending[i];
                if (slow && MapPoint.Distance(s.Position, later.Place.Access) <= later.Radius)
                {
                    for (int k = 0; k < i; k++)
                    {
                        Miss(svc, m, pending[k], now);
                    }
                    return;
                }
            }
            // Passing the current stop without servicing it.
            MissionLeg current = pending[0];
            double d = MapPoint.Distance(s.Position, current.Place.Access);
            if (d <= CareerBalance.BusPassNearMeters)
            {
                current.WasNear = true;
            }
            else if (current.WasNear && d > CareerBalance.BusPassLeaveMeters && current.State != LegState.Servicing)
            {
                Miss(svc, m, current, now);
            }
        }

        private static MissionLeg NextPending(Mission m, MissionLeg after)
        {
            foreach (MissionLeg l in m.Legs)
            {
                if (l.Index > after.Index && !l.IsResolved)
                {
                    return l;
                }
            }
            return null;
        }

        /// <summary>Missed stop: alighting passengers ride to the next stop and complain (SPEC-BUS section 6).</summary>
        private static void Miss(CareerService svc, Mission m, MissionLeg leg, double now)
        {
            BusTerms t = m.Bus;
            ResolveLeg(leg, LegOutcome.Missed, now);
            t.StopsMissed++;
            MissionLeg next = NextPending(m, leg);
            int alight = BusTerms.TakeFrom(t.Onboard, leg.Place.Id);
            if (alight > 0)
            {
                t.Complaints += alight;
                if (next != null)
                {
                    BusTerms.AddTo(t.Onboard, next.Place.Id, alight);
                }
            }
            if (t.WaitingStopId == leg.Place.Id)
            {
                int free = t.Capacity - t.OnboardCount;
                t.Complaints += Math.Min(WaitingTotal(t), Math.Max(0, free));
                t.Waiting.Clear();
                t.WaitingStopId = null;
            }
            svc.Notify(NotificationLevel.Warning, "DTC.Bus.StopMissed", "Stop '" + leg.Place.Name + "' was missed. Passengers complained.", leg.Place.Name);
            if (next != null)
            {
                GenerateWaiting(m, next);
            }
        }

        public override void OnLegDone(CareerService svc, Mission m, MissionLeg leg, PlayerSnapshot s, double now)
        {
            BusTerms t = m.Bus;
            int alight = BusTerms.TakeFrom(t.Onboard, leg.Place.Id);
            t.Delivered += alight;
            if (t.WaitingStopId == leg.Place.Id)
            {
                int free = Math.Max(0, t.Capacity - t.OnboardCount);
                int dwellLimit = (int)Math.Max(0, Math.Floor((CareerBalance.BusDwellCapSeconds - CareerBalance.BusSecondsPerPassenger * alight) / CareerBalance.BusSecondsPerPassenger));
                int boardable = Math.Min(free, dwellLimit);
                int boarded = 0;
                int waiting = WaitingTotal(t);
                foreach (PassengerGroup g in t.Waiting)
                {
                    int n = Math.Min(g.Count, boardable - boarded);
                    if (n <= 0)
                    {
                        break;
                    }
                    BusTerms.AddTo(t.Onboard, g.StopId, n);
                    boarded += n;
                }
                t.Boarded += boarded;
                int leftBehind = waiting - boarded;
                if (leftBehind > 0 && boarded < free)
                {
                    t.Complaints += Math.Min(leftBehind, free - boarded);
                }
                t.Waiting.Clear();
                t.WaitingStopId = null;
            }
            t.StopsServed++;
            double arrival = leg.ArrivedAt >= 0 ? leg.ArrivedAt : now;
            if (leg.TargetTime < 0)
            {
                // First served stop (or first after replanning): it sets the timetable for the following stops.
                t.OnTime++;
                double target = now;
                foreach (MissionLeg l in m.Legs)
                {
                    if (l.Index > leg.Index && !l.IsResolved)
                    {
                        target += l.PlannedSeconds + CareerBalance.BusDwellAllowanceSeconds;
                        l.TargetTime = target;
                    }
                }
            }
            else if (arrival >= leg.TargetTime - CareerBalance.BusEarlyToleranceSeconds && arrival <= leg.TargetTime + CareerBalance.BusLateToleranceSeconds)
            {
                t.OnTime++;
            }
            leg.Outcome = LegOutcome.DoneOk;
            MissionLeg next = NextPending(m, leg);
            if (next != null)
            {
                GenerateWaiting(m, next);
            }
        }

        public override void OnContact(CareerService svc, Mission m, ContactSeverity severity, double now)
        {
            BusTerms t = m.Bus;
            if (t.OnboardCount > 0)
            {
                t.Comfort = CareerMath.Clamp(t.Comfort - ContactPenalty(severity), 0, 100);
            }
            if (severity == ContactSeverity.Severe)
            {
                t.SevereContacts++;
                if (t.SevereContacts >= 3)
                {
                    svc.FinishMission(m, MissionState.Failed, MissionFault.Player, FailSevereKey, "Three severe collisions in one shift. The operator ended your shift.");
                }
            }
        }

        public override double HarshThreshold(Mission m, bool lateral) => (lateral ? 0.35 : 0.3) * CareerBalance.Gravity;

        public override void OnHarsh(CareerService svc, Mission m, bool lateral, double magnitudeMps2, double penaltyMultiplier, double now)
        {
            if (m.Bus.OnboardCount > 0 && magnitudeMps2 >= HarshThreshold(m, lateral))
            {
                m.Bus.Comfort = CareerMath.Clamp(m.Bus.Comfort - CareerBalance.HarshPenalty * penaltyMultiplier, 0, 100);
            }
        }

        public override bool HasObjectsAboard(Mission m) => m.Bus.OnboardCount > 0;

        public override void AbandonLimits(Mission m, out double meters, out double seconds)
        {
            meters = 0;
            seconds = CareerBalance.AbandonSeconds;
        }

        public override void ExtendTimers(Mission m, double seconds)
        {
            foreach (MissionLeg l in m.Legs)
            {
                if (!l.IsResolved && l.TargetTime >= 0)
                {
                    l.TargetTime += seconds;
                }
            }
        }

        /// <summary>Line replanning on revalidation (SPEC-BUS section 8).</summary>
        public override void Revalidate(CareerService svc, Mission m, MapPoint position, double now)
        {
            TransitLineInfo line = svc.FindBusLine(m.Bus.LineId, out bool unknown);
            if (unknown)
            {
                return;
            }
            if (line == null)
            {
                svc.InvalidateMission(m, "DTC.Bus.Invalidated.LineRemoved", "Line " + m.Bus.LineName + " was removed. The shift ended with no fault; served stops were paid in full.", m.Bus.LineName);
                return;
            }
            string sig = Signature(line);
            if (sig == m.Bus.Signature)
            {
                return;
            }
            Replan(svc, m, line, sig, position, now);
        }

        private static int IndexOf(List<PlaceInfo> stops, string id)
        {
            for (int i = 0; i < stops.Count; i++)
            {
                if (stops[i].Id == id)
                {
                    return i;
                }
            }
            return -1;
        }

        private void Replan(CareerService svc, Mission m, TransitLineInfo line, string sig, MapPoint position, double now)
        {
            List<PlaceInfo> s = ValidStops(line);
            var resolved = new List<MissionLeg>();
            var remaining = new List<MissionLeg>();
            foreach (MissionLeg l in m.Legs)
            {
                (l.IsResolved ? resolved : remaining).Add(l);
            }
            int start = -1;
            if (resolved.Count > 0)
            {
                int a = IndexOf(s, resolved[resolved.Count - 1].Place.Id);
                if (a >= 0)
                {
                    start = a + 1;
                }
            }
            if (start < 0)
            {
                foreach (MissionLeg r in remaining)
                {
                    int a = IndexOf(s, r.Place.Id);
                    if (a >= 0)
                    {
                        start = a;
                        break;
                    }
                }
            }
            if (start < 0 && s.Count > 0)
            {
                double best = double.MaxValue;
                for (int i = 0; i < s.Count; i++)
                {
                    double d = MapPoint.Distance(position, s[i].Access);
                    if (d < best)
                    {
                        best = d;
                        start = i;
                    }
                }
            }
            var newStops = new List<PlaceInfo>();
            if (start >= 0)
            {
                int e = IndexOf(s, m.Legs[m.Legs.Count - 1].Place.Id);
                int end = e >= start ? e : s.Count - 1;
                for (int i = start; i <= end; i++)
                {
                    newStops.Add(s[i]);
                }
            }
            // Route checks between consecutive stops; unreachable stops are skipped with no fault (step 5).
            var kept = new List<PlaceInfo>();
            var estimates = new List<RouteEstimate>();
            MapPoint prev = resolved.Count > 0 ? resolved[resolved.Count - 1].Place.Access : position;
            foreach (PlaceInfo p in newStops)
            {
                RouteEstimate e = svc.EstimateRoute(prev, p.Id, VehicleClass.Bus);
                if (!e.IsReachable)
                {
                    continue;
                }
                kept.Add(p);
                estimates.Add(e);
                prev = p.Access;
            }
            if (kept.Count < Math.Min(2, remaining.Count))
            {
                svc.InvalidateMission(m, "DTC.Bus.Invalidated.LineChanged", "Line " + m.Bus.LineName + " no longer serves this shift. The shift ended with no fault; served stops were paid in full.", m.Bus.LineName);
                return;
            }
            var keptIds = new HashSet<string>(StringComparer.Ordinal);
            foreach (PlaceInfo p in kept)
            {
                keptIds.Add(p.Id);
            }
            int removedCount = 0;
            var oldAccess = new Dictionary<string, MapPoint>(StringComparer.Ordinal);
            var remainingIds = new HashSet<string>(StringComparer.Ordinal);
            foreach (MissionLeg r in remaining)
            {
                oldAccess[r.Place.Id] = r.Place.Access;
                remainingIds.Add(r.Place.Id);
                if (!keptIds.Contains(r.Place.Id))
                {
                    removedCount++;
                }
            }
            int addedCount = 0;
            var legs = new List<MissionLeg>(resolved);
            for (int i = 0; i < kept.Count; i++)
            {
                if (!remainingIds.Contains(kept[i].Id))
                {
                    addedCount++;
                }
                int idx = legs.Count;
                legs.Add(Leg(idx, idx, LegKind.Stop, kept[i], CareerBalance.BusStopRadius, estimates[i].DistanceMeters, estimates[i].TimeSeconds, 0));
            }
            for (int i = 0; i < legs.Count; i++)
            {
                legs[i].Index = i;
                legs[i].Group = i;
            }
            m.Legs = legs;

            // Passenger groups headed to removed stops go to the nearest remaining downstream stop (step 3).
            BusTerms t = m.Bus;
            var regrouped = new List<PassengerGroup>();
            foreach (PassengerGroup g in t.Onboard)
            {
                string target = g.StopId;
                if (!keptIds.Contains(target))
                {
                    MapPoint from = oldAccess.ContainsKey(target) ? oldAccess[target] : position;
                    double best = double.MaxValue;
                    foreach (PlaceInfo p in kept)
                    {
                        double d = MapPoint.Distance(from, p.Access);
                        if (d < best)
                        {
                            best = d;
                            target = p.Id;
                        }
                    }
                }
                BusTerms.AddTo(regrouped, target, g.Count);
            }
            t.Onboard = regrouped;
            t.Signature = sig;
            MissionLeg current = m.CurrentLeg;
            if (current != null && t.WaitingStopId != current.Place.Id)
            {
                GenerateWaiting(m, current);
            }
            svc.Notify(NotificationLevel.Warning, "DTC.Bus.LineModified", "Line " + t.LineName + " was modified: " + removedCount + " stop(s) removed, " + addedCount + " added. Passengers were moved to the nearest remaining stops.", t.LineName, CareerMath.Inv(removedCount), CareerMath.Inv(addedCount));
        }

        public override void OnLegInvalid(CareerService svc, Mission m, MissionLeg leg, double now)
        {
            // A single unreachable or missing stop is skipped with no fault; its passengers ride to the next stop.
            BusTerms t = m.Bus;
            ResolveLeg(leg, LegOutcome.SkippedNoFault, now);
            MissionLeg next = NextPending(m, leg);
            int riders = BusTerms.TakeFrom(t.Onboard, leg.Place.Id);
            if (next != null)
            {
                BusTerms.AddTo(t.Onboard, next.Place.Id, riders);
                if (t.WaitingStopId == leg.Place.Id)
                {
                    GenerateWaiting(m, next);
                }
            }
            svc.Notify(NotificationLevel.Warning, "DTC.Bus.StopSkipped", "Stop '" + leg.Place.Name + "' can no longer be reached and was skipped with no fault.", leg.Place.Name);
        }

        public override void OnEnded(Mission m)
        {
            m.Bus.Onboard.Clear();
            m.Bus.Waiting.Clear();
            m.Bus.WaitingStopId = null;
        }

        public override MissionState CompletionOutcome(Mission m) => m.Bus.StopsServed > 0 ? MissionState.Completed : MissionState.Failed;

        /// <summary>Trip evaluation = 35% punctuality + 25% comfort + 25% stops served + 15% cleanliness (SPEC-BUS 6).</summary>
        public static double Evaluation(Mission m)
        {
            BusTerms t = m.Bus;
            int countable = 0;
            foreach (MissionLeg l in m.Legs)
            {
                if (l.Outcome != LegOutcome.SkippedNoFault)
                {
                    countable++;
                }
            }
            double punctuality = t.StopsServed > 0 ? (double)t.OnTime / t.StopsServed : 0;
            double served = countable > 0 ? (double)t.StopsServed / countable : 0;
            return 35 * punctuality + 0.25 * t.Comfort + 25 * served + 0.15 * m.Cleanliness;
        }

        public override SettlementResult Settle(Mission m)
        {
            SettlementResult r = NewResult(m);
            BusTerms t = m.Bus;
            double eval = Evaluation(m);
            r.Evaluation = eval;
            long stops = CareerBalance.BusPerStopCents * t.StopsServed;
            long passengers = CareerBalance.BusPerPassengerCents * t.Delivered;
            int countable = 0;
            foreach (MissionLeg l in m.Legs)
            {
                if (l.Outcome != LegOutcome.SkippedNoFault)
                {
                    countable++;
                }
            }
            double share = countable > 0 ? (double)t.StopsServed / countable : 0;
            if (m.State == MissionState.Completed)
            {
                r.AddLine("DTC.Settle.Bus.Stops", "Stops served (" + t.StopsServed + ")", stops);
                if (passengers > 0)
                {
                    r.AddLine("DTC.Settle.Bus.Passengers", "Career passengers delivered (" + t.Delivered + ")", passengers);
                }
                double punctuality = t.StopsServed > 0 ? (double)t.OnTime / t.StopsServed : 0;
                long bonus = CareerMath.RoundCents((stops + passengers) * CareerBalance.BusPunctualityBonusMax * punctuality);
                if (bonus > 0)
                {
                    r.AddLine("DTC.Settle.Bus.Punctuality", "Punctuality bonus", bonus);
                }
                long subtotal = stops + passengers + bonus;
                long adj = CareerMath.RoundCents(subtotal * Progression.EvaluationMultiplier(eval)) - subtotal;
                if (adj != 0)
                {
                    r.AddLine("DTC.Settle.Evaluation", "Trip evaluation", adj);
                }
                r.Xp = Progression.MissionXp(m.PlannedMeters, eval);
                r.ReputationDelta = Progression.CompletionReputation(eval);
            }
            else if (m.State == MissionState.Cancelled && m.Fault == MissionFault.NoFault)
            {
                if (stops + passengers > 0)
                {
                    r.AddLine("DTC.Settle.Bus.Served", "Served stops (paid in full)", stops + passengers);
                }
                r.Xp = Progression.MissionXp(m.PlannedMeters, eval, share);
            }
            else if (m.State == MissionState.Cancelled)
            {
                long pay = CareerMath.RoundCents((stops + passengers) * 0.5);
                if (pay > 0)
                {
                    r.AddLine("DTC.Settle.Bus.ServedHalf", "Served stops at 50%", pay);
                }
                // Before the shift started the generic Accepted-stage penalty applies (SPEC-MISSION 7.1).
                r.ReputationDelta = m.ActivatedAt < 0 ? -1 : -2;
            }
            else if (m.State == MissionState.Failed)
            {
                r.ReputationDelta = CareerBalance.ReputationFailed;
            }
            return r;
        }
    }
}
